'use strict';
const D=window.ATLAS,M=window.MOCK,L=window.LIBRARY;D.molecules=window.STRUCTURES;
let lang='zh',caseId='A',step=1,searchMode='similarity',threshold=.5,activeCode='DEMO-GC-02',experimentFilter='all';
let librarySource='all',libraryApi='all',libraryQuery='',libraryPage=1,libraryMatch='all';
const versions={A:1,B:1,C:1};
const t=(zh,en)=>lang==='zh'?zh:en;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>{const paths={grid:'<rect x="3" y="3" width="6" height="6"/><rect x="13" y="3" width="6" height="6"/><rect x="3" y="13" width="6" height="6"/><rect x="13" y="13" width="6" height="6"/>',molecule:'<path d="m4 8 6-4 6 4v7l-6 4-6-4zM16 8l4-3M4 15l-3 2M10 4V1"/>',report:'<path d="M5 2h9l4 4v14H5zM14 2v5h4M8 11h7M8 15h7"/>',source:'<path d="M4 5h14v13H4zM7 2h14v13M7 9h8M7 13h5"/>',layers:'<path d="m2 7 9-5 9 5-9 5zM2 12l9 5 9-5M2 17l9 5 9-5"/>',chevron:'<path d="m8 5 6 6-6 6"/>',arrow:'<path d="M4 11h14M13 6l5 5-5 5"/>',download:'<path d="M11 2v12M6 9l5 5 5-5M3 15v5h16v-5"/>',search:'<circle cx="9" cy="9" r="6"/><path d="m14 14 6 6"/>',clock:'<circle cx="11" cy="11" r="8"/><path d="M11 6v5l4 2"/>',check:'<path d="m4 11 5 5 10-11"/>'};return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.grid}</svg>`;};
const badge=c=>`<span class="badge ${c}" title="${c}"><span class="badge-dot" aria-hidden="true"></span>${({REAL:t('真实','Real'),SIMULATED:t('模拟','Simulated'),VIRTUAL:t('虚拟','Virtual'),MISSING:t('缺失','Missing')})[c]}</span>`;
const table=(heads,rows,cls='')=>`<div class="tablewrap ${cls}"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const cases={A:{title:['糖皮质激素','Glucocorticoids'],subtitle:['GR 结合与代谢稳定性','GR binding & metabolic stability'],code:'DEMO-GC-02',project:'GC-01',category:['糖皮质激素系列','Glucocorticoid series']},B:{title:['Brexanolone','Brexanolone'],subtitle:['实验数据补齐','Assay planning'],code:'API-007',project:'NS-01',category:['神经活性甾体','Neuroactive steroid']},C:{title:['雄激素前药','Androgen prodrugs'],subtitle:['酯水解与药代暴露','Ester hydrolysis & exposure'],code:'API-005',project:'PK-01',category:['前药与药代','Prodrugs & pharmacokinetics']}};
const names=[['结构输入','Structure'],['理化属性','Properties'],['骨架识别','Scaffold'],['项目登记','Project'],['结构索引','Index'],['结构检索','Search'],['实验记录','Experiments'],['分析输入','Context'],['SAR 分析','Analysis'],['结构设计','Design'],['研究报告','Report']];
const currentView=()=>['home','library','workbench','report','evidence','platform'].includes(location.hash.slice(1))?location.hash.slice(1):'home';
const molecule=()=>D.molecules.find(m=>m.demo_code===(caseId==='A'?activeCode:cases[caseId].code));
const selected=()=>caseId==='A'?D.molecules.filter(m=>m.demo_code.startsWith('DEMO')):[molecule()];
const projectTitle=()=>cases[caseId].title[lang==='zh'?0:1];
const empty=(title,body)=>`<div class="empty-state">${icon('source')}<h3>${title}</h3><p>${body}</p>${badge('MISSING')}</div>`;
const legend=()=>`<details class="legend"><summary>${t('数据类型','Data types')}</summary><div>${['REAL','SIMULATED','VIRTUAL','MISSING'].map((c,i)=>`<span>${badge(c)}${[t('公开结构 / 计算值','Public structures / computed values'),t('人为构造的实验数据','Illustrative assay values'),t('未测试结构与研究假设','Untested structures & hypotheses'),t('尚未取得的数据','Unavailable evidence')][i]}</span>`).join('')}</div></details>`;
const sectionHead=(title,action='')=>`<div class="sectionhead"><h2>${title}</h2>${action}</div>`;
function experiments(){let e=caseId==='A'?D.experiments:[];return [...e,...M.pk.filter(x=>x.case===caseId),...M.safety.filter(x=>x.case===caseId),...(versions[caseId]===2?[{...M.loops[caseId],name:t('下一轮候选','Next-round candidate'),assay_type:caseId==='C'?'pk':caseId==='B'?'other':'adme',protocol:'SIM-ROUND-02',species:caseId==='C'?'rat':caseId==='B'?'not specified':'human'}]:[])];}
function loopText(){return lang==='zh'?M.loops[caseId].zh.replaceAll('示例',''):M.loops[caseId].en.replace(/\billustrative\s+/ig,'');}
function analysisText(){if(versions[caseId]===2)return loopText();if(caseId==='A')return t('四个参考分子的 TPSA、HBA、HBD 和环数相同。Dexamethasone 与 Betamethasone 的非手性指纹相似度为 1.000，但完整立体身份不同。当前 GR 与微粒体记录均为模拟数据；下一步需补充同条件重复测定。','The four reference molecules have identical TPSA, HBA, HBD and ring count. Dexamethasone and betamethasone have non-chiral similarity 1.000, but distinct stereochemical identities. GR and microsomal records are simulated; matched replicate assays are required.');if(caseId==='B')return t('已取得结构与计算属性；尚无可用于比较的 Biology、ADME、PK 或 Safety 数据。先完成身份、纯度与实验体系确认，再建立带重复与对照的实验记录。','Structure and computed properties are available. Comparable Biology, ADME, PK and Safety records are missing. Confirm identity, purity and assay setup, then establish replicates and controls.');return t('酯水解、制剂和吸收条件均可能影响口服暴露。当前 PK 与安全性记录为模拟值，尚不足以评价前药收益。建议建立同剂量母体 / 前药对照，分别记录完整前药与母体的浓度。','Ester hydrolysis, formulation and absorption may affect oral exposure. Current PK and safety records are simulated, so prodrug benefit remains unassessed. Compare parent and prodrug at matched doses and quantify both separately.');}
function loopPlan(){return caseId==='A'?t('同条件测定 GR 结合与微粒体稳定性，补充重复及误差。30 分钟剩余比例低于 50% 时，修改当前结构路线。','Measure matched GR binding and microsomal stability with replicates and uncertainty. Modify the current route below 50% remaining at 30 min.'):caseId==='B'?t('核验身份与纯度，建立至少三次重复及对照。对照失效时暂停解释结果。','Verify identity and purity; establish at least three replicates and controls. Suspend interpretation if controls fail.'):t('同剂量比较母体 / 前药水解与暴露。AUC0–24 低于 240 ng·h/mL 时停止当前路线，并复核制剂因素。','Compare parent / prodrug hydrolysis and exposure at matched doses. Stop below AUC0–24 of 240 ng·h/mL and review formulation.');}
function descriptorMetrics(mol){return `<div class="metrics">${['mw','clogp','tpsa','hba','hbd','fsp3','ring_count'].map(k=>`<div class="metric"><span>${{mw:'MW',clogp:'cLogP',tpsa:'TPSA',hba:'HBA',hbd:'HBD',fsp3:'Fsp3',ring_count:t('环数','Rings')}[k]}</span><strong>${esc(mol.descriptors[k])}</strong><small>${k==='mw'?'g/mol':k==='tpsa'?'Å²':t('计算值','Computed')}</small></div>`).join('')}</div>`;}
function moleculeRows(){return selected().map(m=>{let first=caseId==='C'?M.pk.find(x=>x.case==='C'):D.experiments.find(x=>x.demo_code===m.demo_code&&x.assay_type==='biology');let second=caseId==='C'?M.safety.find(x=>x.case==='C'):D.experiments.find(x=>x.demo_code===m.demo_code&&x.assay_type==='adme');return [`<button class="molecule-link" data-mol="${m.demo_code}"><img src="assets/${m.demo_code}.svg" alt=""><span><b>${esc(m.name)}</b><small>${esc(m.demo_code)}</small></span></button>`,`${esc(m.descriptors.mw)} ${badge('REAL')}`,`${esc(m.descriptors.clogp)} ${badge('REAL')}`,`${first?first.value+' <small>'+esc(first.unit)+'</small> '+badge('SIMULATED'):badge('MISSING')}`,`${second?second.value+' <small>'+esc(caseId==='C'?second.unit:'%')+'</small> '+badge('SIMULATED'):badge('MISSING')}`,`<button class="text-button" data-mol="${m.demo_code}" aria-label="${t('打开','Open')} ${esc(m.name)}">${t('打开','Open')} ${icon('chevron')}</button>`];});}

function dashboard(){const mol=molecule(),exps=experiments(),loop=M.loops[caseId];return `${dataCoverage()}<div class="pageheading"><div><div class="breadcrumb">${t('研发项目','Research projects')} / ${cases[caseId].project}</div><h1>${projectTitle()}</h1><p>${cases[caseId].subtitle[lang==='zh'?0:1]}</p></div><button class="primary" data-view="workbench">${t('打开工作台','Open workbench')}${icon('arrow')}</button></div><div class="summary-strip"><div><span>${t('系列分子','Series molecules')}</span><b>${selected().length}</b>${badge('REAL')}</div><div><span>${t('实验记录','Assay records')}</span><b>${exps.length}</b>${badge(exps.length?'SIMULATED':'MISSING')}</div><div><span>${t('结构候选','Design candidates')}</span><b>${caseId==='A'?D.candidates.length:'—'}</b>${badge(caseId==='A'?'VIRTUAL':'MISSING')}</div><div><span>${t('项目版本','Project version')}</span><b>v${versions[caseId]}</b><small>${t('当前快照','Current snapshot')}</small></div></div><div class="overview-grid"><section class="card molecule-card"><div class="sectionhead"><h2>${t('当前分子','Current molecule')}</h2>${badge('REAL')}</div><div class="molecule-view"><img src="assets/${mol.demo_code}.svg" alt="${esc(mol.name)} molecular structure"></div><div class="molecule-title"><h3>${esc(mol.name)}</h3><span class="subtle">${cases[caseId].category[lang==='zh'?0:1]}</span></div><div class="property-row"><span>MW <b>${mol.descriptors.mw}</b></span><span>cLogP <b>${mol.descriptors.clogp}</b></span><span>TPSA <b>${mol.descriptors.tpsa}</b></span></div><p class="identity mono">${esc(mol.inchikey)}</p></section><section class="card research-card">${sectionHead(t('研究记录','Research notes'),`<span class="review-status">${t('待复核','Review pending')}</span>`)}<div class="note-row"><span class="note-type">${t('分析','Analysis')}</span><div><p>${esc(analysisText())}</p><small>${caseId==='C'||versions[caseId]===2?badge('SIMULATED'):t('Codex · 已保存','Codex · saved')+' '+badge('VIRTUAL')}</small></div></div><div class="note-row"><span class="note-type">${t('实验','Experiment')}</span><div><p>${loopPlan()}</p>${badge('SIMULATED')}<small>${t('实验方案参数','Experiment plan parameters')}</small></div></div><div class="card-bottom"><button class="text-button" data-step-jump="9">${t('查看分析记录','View analysis')}${icon('chevron')}</button><a href="#report" class="text-button">${t('研究报告','Research report')}${icon('chevron')}</a></div></section></div><section class="card series-card">${sectionHead(t('分子列表','Molecules'),`<span class="subtle">${caseId==='C'?'PK / Safety':caseId==='B'?'Biology / ADME':t('GR Ki · 微粒体 30 min 剩余比例','GR Ki · microsomal remaining at 30 min')}</span>`)}${table([t('分子','Molecule'),'MW','cLogP',caseId==='C'?'AUC0–24':caseId==='B'?'Biology':'GR Ki',caseId==='C'?'hERG IC50':caseId==='B'?'ADME':t('微粒体稳定性','Microsomal stability'),`<span class="sr-only">${t('操作','Actions')}</span>`],moleculeRows())}</section><div class="lower-grid"><section class="card">${sectionHead(t('下一轮实验','Next experiment'),badge('SIMULATED'))}<p>${loopPlan()}</p><div class="card-bottom"><span class="subtle">${versions[caseId]===1?t('待录入结果','Awaiting results'):t('已录入模拟结果','Simulated result loaded')}</span><button class="text-button" data-step-jump="7">${t('实验记录','Assay records')}${icon('chevron')}</button></div></section><section class="card">${sectionHead(t('决策记录','Decision log'))}<div class="decision-entry"><span class="version">v${versions[caseId]}</span><div><b>${versions[caseId]===1?t('等待实验数据','Awaiting assay data'):decisionLabel(loop.decision)}</b><p>${versions[caseId]===1?t('当前结构路线待验证。','Current route awaits validation.'):esc(loopText())}</p></div>${badge(versions[caseId]===1?'VIRTUAL':'SIMULATED')}</div></section></div>`;}
function decisionLabel(decision){return {modify:t('修改路线','Modify route'),stop:t('停止路线','Stop route'),continue:t('继续研究','Continue research')}[decision];}
function experimentTable(){let exps=experiments().filter(x=>experimentFilter==='all'||(x.assay_type|| (x.assay.includes('hERG')?'safety':'pk'))===experimentFilter);return exps.length?table([t('分子','Molecule'),t('实验','Assay'),t('结果','Result'),t('协议 / 物种','Protocol / species'),t('类型','Class')],exps.map(x=>[esc(x.name),esc(x.assay_name||x.assay),`<strong>${esc(x.value)}</strong> <small>${esc(x.unit)}</small>`,`<span class="mono">${esc(x.protocol)}<br>${esc(x.species)}</span>`,badge(x.data_class)])):empty(t('暂无实验记录','No assay records'),t('补充测定方案、实验条件与结果。','Add assay plans, conditions and results.'));}
function candidateCards(){return `<div class="candidate-grid">${D.candidates.map((c,i)=>`<article class="candidate"><div class="sectionhead"><h3>${i===0?t('末端 O-乙酰化','Terminal O-acetylation'):t('末端 O-甲基化','Terminal O-methylation')}</h3>${badge('VIRTUAL')}</div><span class="subtle">Hydrocortisone · VIRTUAL_UNTESTED</span><p>${i===0?t('通过酯化掩蔽末端羟基；重点测定水解、母体生成及受体结合。','Mask the terminal hydroxyl via esterification; measure hydrolysis, parent formation and receptor binding.'):t('通过醚化减少一个供氢基团；比较溶解度、logD 与代谢变化。','Reduce one hydrogen-bond donor via etherification; compare solubility, logD and metabolism.')}</p><div class="candidate-values"><span>MW <b>${c.check.descriptor.mw}</b></span><span>cLogP <b>${c.check.descriptor.clogp}</b></span><span>TPSA <b>${c.check.descriptor.tpsa}</b></span>${badge('REAL')}</div><details><summary>${t('结构与验证计划','Structure & validation plan')}</summary><p class="mono">${esc(c.hypothesis.candidate.smiles)}</p><p>${lang==='zh'?esc(c.hypothesis.validation):t('','Verify identity and purity, then run matched binding, stability, solubility and logD assays.')}</p></details><span class="review-status">${t('未合成 · 未测试 · 未查新','Unsynthesized · untested · novelty unchecked')}</span></article>`).join('')}</div>`;}
function analysisPanel(){return `<div class="analysis-meta">${badge(caseId==='C'||versions[caseId]===2?'SIMULATED':'VIRTUAL')}<span>${caseId==='C'||versions[caseId]===2?t('模拟研究记录','Illustrative research record'):t('Codex · 已保存分析','Codex · saved analysis')}</span><span class="review-status">${t('专业复核待完成','Professional review pending')}</span></div><h3>${t('分析摘要','Summary')}</h3><p>${esc(analysisText())}</p>${caseId==='A'?`<div class="finding-list"><div><b>${t('立体身份','Stereochemical identity')}</b><p>${t('Dex / Beta：相似度 1.000；InChIKey 不同。','Dex / Beta: similarity 1.000; distinct InChIKeys.')}</p>${badge('REAL')}</div><div><b>${t('同条件实验','Matched assays')}</b><p>${t('GR Ki 与微粒体稳定性分别按协议比较。','Compare GR Ki and microsomal stability within each protocol.')}</p>${badge('SIMULATED')}</div><div><b>${t('待补证据','Outstanding evidence')}</b><p>${t('真实重复、误差、专业 SAR 文献。','Real replicates, uncertainty and reviewed SAR literature.')}</p>${badge('MISSING')}</div></div>`:''}<details class="research-note"><summary>${t('研究笔记','Research note')} ${badge('SIMULATED')}</summary><p>${t('酯化可能影响脂溶性与释放过程。下一轮需同时考察水解、暴露与制剂因素。','Esterification may affect lipophilicity and release. Assess hydrolysis, exposure and formulation together.')}</p><p class="subtle">${t('模拟文献 SAR 内容；没有真实论文引用。','Illustrative literature-SAR content; no actual publication citation.')}</p></details>`;}
function stepContent(){const mol=molecule();switch(step){case 1:return `<div class="formhead">${badge('REAL')}<span class="subtle">${t('公开参考结构','Public reference structure')}</span></div><label class="field" for="smiles">SMILES</label><textarea id="smiles" spellcheck="false">${esc(mol.smiles)}</textarea><div class="formactions"><button id="normalize" class="primary">${t('读取标准结构','Load canonical structure')}</button><span class="subtle">${t('预计算记录','Precomputed record')} · RDKit 2026.03.3</span></div><span id="inputstatus" class="status" role="status"></span><div id="canonical" class="hidden"></div><details class="method"><summary>${t('标准化设置','Normalization settings')}</summary><p>${t('保留立体标记；盐型与互变异构体标准化待补。当前可读取七个参考结构的预计算记录。','Retain stereochemistry. Comprehensive salt / tautomer normalization is pending. Precomputed records are available for seven reference structures.')}</p></details>`;
case 2:return `<div class="formhead">${badge('REAL')}<span class="subtle">RDKit 2026.03.3 · ${t('计算值','Computed values')}</span></div>${descriptorMetrics(mol)}<p class="caption">${t('当前分子','Current molecule')}: ${esc(mol.name)}</p>${caseId==='A'?table([t('系列分子','Series molecule'),'MW','cLogP','TPSA','HBA','HBD','Fsp3',t('环数','Rings')],selected().map(m=>[esc(m.name),...['mw','clogp','tpsa','hba','hbd','fsp3','ring_count'].map(k=>m.descriptors[k])])):''}`;
case 3:return `<div class="scaffold-grid"><article class="scaffold"><img src="assets/${mol.demo_code}.svg" alt="${esc(mol.name)} structure"><div>${badge('REAL')}<h3>${esc(mol.name)}</h3><p class="pass">${icon('check')}${t('甾体骨架匹配','Steroid scaffold matched')}</p><span class="subtle">6–6–6–5 · ${t('稠合环系','Fused ring system')}</span></div></article><article class="scaffold"><img src="assets/API-011.svg" alt="Treprostinil structure"><div>${badge('REAL')}<h3>Treprostinil</h3><p>${t('非甾体 · 排除','Non-steroid · excluded')}</p><span class="subtle">${t('骨架识别负对照','Negative scaffold control')}</span></div></article></div>`;
case 4:return `<div class="project-facts"><div><span>${t('项目','Project')}</span><b>${cases[caseId].project} · ${projectTitle()}</b></div><div><span>${t('系列','Series')}</span><b>${cases[caseId].category[lang==='zh'?0:1]}</b></div><div><span>${t('项目版本','Project version')}</span><b>v${versions[caseId]}</b></div></div>${table([t('化合物','Compound'),t('编号','Identifier'),t('描述符','Descriptors'),t('记录类型','Record type')],selected().map(m=>[esc(m.name),esc(m.demo_code),'RDKit 2026.03.3',badge('REAL')]))}`;
case 5:return `<div class="formhead">${badge('REAL')}<span class="subtle">${t('结构指纹记录','Structure fingerprint record')}</span></div>${table([t('索引字段','Index field'),t('设置','Setting')],[['Molecule',esc(mol.name)],['Fingerprint','Morgan'],['Radius','2'],['Bits','2048'],['Chirality',t('不纳入相似度计算','Excluded from similarity')],['Identity','Full InChIKey']])}<p class="mono identity">${esc(mol.inchikey)}</p>`;
case 6:return `<div class="tabs">${['exact','substructure','similarity'].map(x=>`<button data-search="${x}" class="${searchMode===x?'active':''}" aria-pressed="${searchMode===x}">${({exact:t('精确结构','Exact structure'),substructure:t('子结构','Substructure'),similarity:t('相似结构','Similarity')})[x]}</button>`).join('')}</div><div class="search-controls"><div><span class="field">${t('查询分子','Query molecule')}</span><strong>${esc(mol.name)}</strong><small>${t('预计算索引 · 七个结构','Precomputed index · seven structures')}</small></div>${searchMode==='similarity'?`<div><label class="field" for="threshold">${t('相似度阈值','Similarity threshold')} <span id="thresholdvalue">${threshold}</span></label><input type="range" id="threshold" min="0" max="1" step="0.1" value="${threshold}"></div>`:`<div class="subtle">${searchMode==='substructure'?'Bemis–Murcko · '+t('忽略手性','non-chiral'):t('完整立体身份匹配','Full stereochemical identity')}</div>`}</div><div id="searchresults">${searchResults()}</div>`;
case 7:return `<div class="tabs">${['all','biology','adme','pk','safety'].map(x=>`<button data-assay="${x}" class="${experimentFilter===x?'active':''}" aria-pressed="${experimentFilter===x}">${x==='all'?t('全部','All'):x==='biology'?'Biology':x==='adme'?'ADME':x.toUpperCase()}</button>`).join('')}</div><div id="experimentresults">${experimentTable()}</div><span class="caption">${t('模拟实验数据 · 记录包含协议、单位与物种','Simulated assay data · protocols, units and species retained')}</span>`;
case 8:return `<div class="analysis-meta"><span>${caseId==='C'?t('研究输入清单','Research input manifest'):t('Codex 分析 · 已保存输入','Codex analysis · saved input')}</span>${badge('REAL')}</div>${table([t('输入项','Input'),t('状态','Status'),t('记录','Record')],[[t('结构与描述符','Structure & descriptors'),badge('REAL'),selected().length+' '+t('个分子','molecules')],[t('实验数据','Assays'),badge(caseId==='B'?'MISSING':'SIMULATED'),t('原始归档输入；模拟 PK 另列','Original archived input; mock PK separate')],[t('专业 SAR 文献','Reviewed SAR literature'),badge('MISSING'),t('待补引用','References pending')]])}<details class="method"><summary>SHA-256 · ${caseId==='C'?t('公开结构清单','Public structure manifest'):t('原分析输入','Original analysis input')}</summary><p class="mono">${esc(caseId==='C'?mol.sha256:D.analysis[caseId].sha256)}</p><p class="subtle">${t('输入指纹对应原归档记录。新模拟结果与更新后的研究判断单独保存。','The fingerprint identifies the original archive. New simulated results and revised notes are stored separately.')}</p></details>`;
case 9:return analysisPanel();
case 10:return `${caseId==='A'?candidateCards():''}<h3 class="subheading">${t('待研究方向','Research directions')}</h3>${M.modifications.map(m=>`<div class="direction-row"><b>${esc(m.name)}</b><span>${esc(m[lang])}</span>${badge('VIRTUAL')}</div>`).join('')}<p class="caption">VIRTUAL_UNTESTED · ${t('未合成 / 未测试 / 未查新','Unsynthesized / untested / novelty unchecked')}</p>`;
case 11:return `<div class="report-cover"><span class="report-id">${cases[caseId].project} / v${versions[caseId]}</span><h3>${projectTitle()} · ${t('研究报告','Research report')}</h3><p>${esc(analysisText())}</p><div class="formactions"><a class="button primary" href="#report">${t('打开报告','Open report')}${icon('arrow')}</a><button data-download="html">${icon('download')} HTML</button><button data-download="json">${icon('download')} JSON</button></div></div>`;}}
function searchResults(){const q=molecule();const r=window.SEARCH.filter(x=>x.query===q.demo_code&&(searchMode==='exact'?x.exact:searchMode==='substructure'?x.substructure:x.score>=threshold)).sort((a,b)=>b.score-a.score);return r.length?table([t('排名','Rank'),t('分子','Molecule'),searchMode==='similarity'?'Tanimoto':'InChIKey',t('类型','Class')],r.map((x,i)=>{const m=D.molecules.find(m=>m.demo_code===x.target);return[i+1,`<button class="molecule-link" data-mol="${m.demo_code}">${esc(m.name)}</button>`,searchMode==='similarity'?x.score.toFixed(6):`<span class="mono">${esc(m.inchikey)}</span>`,badge('REAL')];})):empty(t('未找到匹配结构','No matching structures'),t('调整相似度阈值或查询分子。','Adjust the similarity threshold or query molecule.'));}
function workbench(){const mol=molecule();return `<div class="pageheading"><div><div class="breadcrumb">${projectTitle()} / ${t('分子工作台','Molecular workbench')}</div><h1>${esc(mol.name)}</h1></div><a href="#report" class="button">${icon('report')}${t('研究报告','Research report')}</a></div><div class="workbench"><div class="rail" aria-label="11-step workflow">${names.map((n,i)=>`<button data-step="${i+1}" class="${step===i+1?'active':''}" aria-current="${step===i+1?'step':'false'}"><span>${String(i+1).padStart(2,'0')}</span>${n[lang==='zh'?0:1]}</button>`).join('')}</div><div class="panel"><aside class="molecule-sidebar"><span class="small-label">${t('系列分子','Series molecule')}</span>${caseId==='A'?`<label class="sr-only" for="molecule">${t('选择分子','Select molecule')}</label><select id="molecule">${selected().map(m=>`<option value="${m.demo_code}" ${m.demo_code===activeCode?'selected':''}>${esc(m.name)}</option>`).join('')}</select>`:`<h3>${esc(mol.name)}</h3>`}<img src="assets/${mol.demo_code}.svg" alt="${esc(mol.name)} structure"><span class="mono">${esc(mol.demo_code)}</span>${badge('REAL')}<dl><dt>MW</dt><dd>${mol.descriptors.mw}</dd><dt>cLogP</dt><dd>${mol.descriptors.clogp}</dd><dt>TPSA</dt><dd>${mol.descriptors.tpsa}</dd></dl><p class="mono identity">${esc(mol.inchikey)}</p><a class="text-button" href="#evidence">${t('来源记录','Source records')}${icon('chevron')}</a></aside><div class="panelbody"><div class="stephead"><div><span class="small-label">${String(step).padStart(2,'0')} / 11</span><h2>${names[step-1][lang==='zh'?0:1]}</h2></div><span class="version">v${versions[caseId]}</span></div>${stepContent()}</div></div><div class="panelactions"><button id="prev" ${step===1?'disabled':''}>${t('上一步','Previous')}</button><span class="subtle">${names[step-1][lang==='zh'?0:1]}</span><button id="next" class="primary">${step===11?t('下一轮实验','Next experiment'):t('下一步','Next')}${icon('arrow')}</button></div></div>${loopPanel()}`;}
function loopPanel(){const l=M.loops[caseId];return `<section class="card loop" id="loop"><div class="sectionhead"><h2>${t('下一轮实验','Next experiment')}</h2>${badge('SIMULATED')}</div><div class="loop-grid"><div><span class="small-label">${t('实验方案','Experiment plan')}</span><p>${loopPlan()}</p><span class="subtle">${t('参数与结果均为模拟数据','Parameters and results are simulated')}</span></div><div class="loop-action">${versions[caseId]===1?`<p class="subtle">${t('结果待录入','Awaiting result')} · v1</p><button id="record" class="primary">${t('载入模拟结果','Load simulated result')}${icon('arrow')}</button>`:`<div role="status"><span class="version">v2</span><b>${decisionLabel(l.decision)}</b><p>${esc(loopText())}</p></div><button id="reset">${t('返回 v1','Return to v1')}</button>`}</div></div><div class="loop-trace"><span>${t('实验记录','Assay record')}</span>${icon('arrow')}<span>${t('分析输入','Analysis input')}</span>${icon('arrow')}<span>${t('SAR 分析','SAR analysis')}</span>${icon('arrow')}<span>${t('项目决策','Project decision')}</span></div></section>`;}
function reportView(){return `<div class="pageheading"><div><div class="breadcrumb">${projectTitle()} / ${t('研究报告','Research report')}</div><h1>${t('研究报告','Research report')}</h1></div><div class="formactions"><button data-download="html">${icon('download')} HTML</button><button data-download="json" class="primary">${icon('download')} JSON</button></div></div><div class="report-layout"><article class="reportpaper"><div class="document-meta">${cases[caseId].project} <span>v${versions[caseId]}</span></div><h2>${projectTitle()}</h2><p class="subtle">${cases[caseId].subtitle[lang==='zh'?0:1]}</p><div class="report-section"><h3>01 · ${t('研究判断','Assessment')}</h3>${analysisPanel()}</div><div class="report-section"><h3>02 · ${t('结构与属性','Structures & properties')}</h3>${badge('REAL')}<span class="subtle"> RDKit · ${t('计算值','computed values')}</span>${table([t('分子','Molecule'),'MW','cLogP','TPSA'],selected().map(m=>[esc(m.name),m.descriptors.mw,m.descriptors.clogp,m.descriptors.tpsa]))}</div><div class="report-section"><h3>03 · ${t('下一轮实验','Next experiment')}</h3>${badge('SIMULATED')}<p>${loopPlan()}</p>${versions[caseId]===2?`<p>${esc(loopText())}</p>`:''}</div><div class="report-section"><h3>04 · ${t('待补资料','Outstanding evidence')}</h3>${badge('MISSING')}<p>${t('真实可比实验、重复与误差、专业 SAR 文献、安全性与合成可行性复核。','Comparable measured assays, replicates and uncertainty, reviewed SAR literature, safety and synthetic feasibility review.')}</p></div></article><aside class="report-side card"><h2>${t('记录信息','Record information')}</h2><dl><dt>${t('项目','Project')}</dt><dd>${cases[caseId].project}</dd><dt>${t('版本','Version')}</dt><dd>v${versions[caseId]}</dd><dt>${t('内容状态','Review status')}</dt><dd>${t('专业复核待完成','Professional review pending')}</dd><dt>${t('分析来源','Analysis source')}</dt><dd>${caseId==='C'||versions[caseId]===2?t('模拟研究记录','Illustrative record'):t('已保存 Codex 分析','Saved Codex analysis')}</dd></dl><details><summary>SHA-256</summary><p class="mono">${esc(caseId==='C'?molecule().sha256:D.analysis[caseId].sha256)}</p><small>${caseId==='C'?t('公开结构清单','Public structure manifest'):t('原始归档输入','Original archived input')}</small></details><a class="text-button" href="#evidence">${t('来源与方法','Sources & methods')}${icon('chevron')}</a></aside></div>`;}
function sourcesView(){return `<div class="pageheading"><div><div class="breadcrumb">${projectTitle()} / ${t('来源与记录','Sources & records')}</div><h1>${t('来源与记录','Sources & records')}</h1></div></div><section class="card">${sectionHead(t('结构来源','Structure sources'))}${table([t('分子','Molecule'),t('来源','Source'),t('身份','Identity'),t('类型','Class')],selected().map(m=>[esc(m.name),m.source.startsWith('https://')?`<a class="source-link" href="${esc(m.source)}" target="_blank" rel="noopener">PubChem ${icon('arrow')}</a>`:'PubChem · '+t('已核对结构清单','Verified structure manifest'),`<span class="mono">${esc(m.inchikey)}</span>`,badge('REAL')]))}</section><div class="lower-grid"><section class="card"><h2>${t('计算与检索','Computation & retrieval')}</h2><dl class="method-list"><dt>RDKit</dt><dd>2026.03.3 · ${t('计算属性，非实测物性','Computed, not measured')}</dd><dt>Morgan</dt><dd>radius 2 / 2048 bits / ${t('非手性','non-chiral')}</dd><dt>${t('子结构','Substructure')}</dt><dd>Bemis–Murcko · ${t('忽略手性','non-chiral')}</dd><dt>${t('标准化','Normalization')}</dt><dd>${t('保留立体标记；全面盐型 / 互变异构体标准化待补','Stereochemistry retained; full salt / tautomer handling pending')}</dd></dl></section><section class="card"><h2>${t('数据状态','Data status')}</h2><div class="source-note">${badge('SIMULATED')}<p>${t('GR / ADME、PK / Safety、下一轮实验与文献 SAR 卡为人为构造的数据。','GR / ADME, PK / Safety, next-round experiments and the literature-SAR card contain illustrative data.')}</p></div><div class="source-note">${badge('VIRTUAL')}<p>${t('结构候选未合成、未实测、未查新。专业 SAR 与风险复核待完成。','Candidates are unsynthesized, untested and not novelty-reviewed. Professional SAR and risk review are pending.')}</p></div></section></div><section class="card"><h2>${t('分析与版本','Analysis & version history')}</h2>${table([t('记录','Record'),t('来源','Source'),t('状态','Status')],[['GC-01 / NS-01',t('保存的 Codex 对话分析','Saved Codex conversation analysis'),t('非实时模型调用 · 待复核','No live model call · pending review')],['PK-01',t('模拟研究记录','Illustrative research record'),badge('SIMULATED')],['v2',t('预写模拟结果与研究判断','Canned simulated result & assessment'),badge('SIMULATED')]])}<details class="method"><summary>${t('版本关联','Version binding')}</summary><p>${t('SHA 对应原始归档输入。新增模拟 PK 与 v2 回流单独记录，不作为原分析的输入。','SHA identifies the original archived input. Added mock PK and v2 feedback remain separate from the original analysis input.')}</p></details></section><details class="card technical-record"><summary>${t('数据使用说明','Data use details')}</summary><dl class="method-list"><dt>${t('运行模式','Runtime')}</dt><dd>${t('静态样例工作空间；无数据库写入','Static sample workspace; no database writes')}</dd><dt>${t('分析模式','Analysis')}</dt><dd>${t('保存的 Codex 分析；非实时推理','Saved Codex analysis; no live inference')}</dd><dt>${t('来源许可','Licensing')}</dt><dd>${t('仅公开来源；商业许可内容不发布','Public sources only; licensed content excluded')}</dd><dt>${t('效果测量','Impact')}</dt><dd>${t('未测量','Unmeasured')}</dd></dl></details>`;}
function platformView(){return `<div class="pageheading"><div><div class="breadcrumb">${t('情报档案','Intelligence dossiers')}</div><h1>API 360</h1><p>${t('试点原料药 · 公开来源覆盖','Pilot APIs · public-source coverage')}</p></div><a class="button" href="#library">${t('资料库','Source library')}${icon('arrow')}</a></div>${dataCoverage()}<section class="card">${sectionHead(t('原料药资料覆盖','API source coverage'),`<span class="subtle">${t('公开关联记录','Public associated records')} ${badge('REAL')}</span>`)}${table([t('原料药','API'),'PubChem','ClinicalTrials.gov','PubMed','openFDA','Orange Book',t('合计','Total')],L.compounds.map(c=>[`<button class="molecule-link" data-library-api="${c.code}"><span><b>${esc(c.name)}</b><small>${c.code}</small></span></button>`,...['pubchem','clinical_trials','pubmed','openfda_label','orange_book'].map(k=>formatCount(c.counts[k]||0)),`<b>${formatCount(c.records)}</b>`]))}<p class="caption">${t('同一文档可关联多个原料药；关联数与去重文档数分别统计。','A document may be associated with several APIs; associations and unique documents are counted separately.')}</p></section>`;}

const formatCount=x=>Number(x).toLocaleString('en-US');
function expansionEstimate(){
const counted=[['学术文献','Research literature','650,044–677,441','PubMed',t('全目录名称检索 → 扩展母体名称；查询内去重','Catalogue names → parent-name expansion; deduplicated within query')],['临床试验登记','Clinical trial registrations','20,397','ClinicalTrials.gov',t('34 个母体／活性成分名称联合检索；全状态、无条数截断','Joint search of 34 parent / active ingredient names; all statuses, uncapped')],['标签／说明书','Labels / prescribing information','2,834','openFDA',t('全目录＋母体名称；包含不同标签版本','Catalogue + parent names; includes label versions')],['美国上市产品','US approved products','2,542','Orange Book',t('完整文件成分匹配；含已停产产品、复方与规格','Ingredient matching against full file; includes discontinued products, combinations and strengths')],['美国注册申请主体','US product applicants','390','Orange Book',t('申请人原文去重；未合并集团实体','Distinct applicant strings; corporate groups not resolved')],['美国产品关联专利','US product-linked patents','292',t('Orange Book 专利文件','Orange Book patent file'),t('292 个专利号／631 条产品关联；不是全球专利总量','292 patent numbers / 631 product links; not the global patent total')]];
const scenarios=[['分子身份与计算属性','Molecular identity & computed properties','60 '+t('档案＋420 项属性','profiles + 420 properties'),t('官网 61 个目录条目中排除 1 个明确中间体；每结构 7 项描述符','61 catalogue entries minus one explicit intermediate; seven descriptors per structure')],['靶点与作用机制','Targets & mechanisms','60–600',t('每目录品种 1–10 条关联，按 60 个品种测算','1–10 associations per catalogue product × 60')],['适应证与用药背景','Indications & treatment context','34–680',t('每母体 1–20 条关联，按 34 个检索名称测算','1–20 associations per parent search name × 34')],['同系列分子与产业关系','Related molecules & industry relationships','600–6,000',t('每品种 10–100 条关系，包含衍生物、盐型与产业关联','10–100 relationships per product, including derivatives, salts and industry links')],['全球产品与制剂','Global products & formulations','2,500–25,000',t('以美国完整产品匹配量为锚，全球覆盖按约 1–10 倍设置容量情景','Full US product match count anchors a roughly 1–10× global capacity scenario')],['全球监管与注册事件','Global regulatory & registration events','5,000–100,000',t('2,500–25,000 产品 × 每产品 2–4 类事件；批准、变更等','2,500–25,000 products × 2–4 events per product, including approvals and changes')],['全球竞争企业','Global competitor entities','400–4,000',t('美国 390 个申请人名称为锚；全球按约 1–10 倍，需实体合并','390 US applicant names anchor a roughly 1–10× global scenario; entity resolution required')],['全球专利与工艺专利','Global patents & process patents','6,000–60,000',t('每品种 100–1,000 个检索线索 × 60；需专利族合并和归属复核','100–1,000 search leads per product × 60; family consolidation and relevance review required')],['临床方案／终点／结果','Clinical protocols / endpoints / results','60,000–200,000',t('约 2 万项登记 × 每项 3–10 个字段组；结果缺失不补造','About 20,000 registrations × 3–10 field groups each; missing results remain missing')],['Biology / ADME / PK / Safety','Biology / ADME / PK / Safety','35,000–1,400,000',t('约 70 万检索记录 × 1%–10% 可提取比例 × 每篇 5–20 条实验对象','About 700,000 search records × 1%–10% extractable fraction × 5–20 assay objects per paper')],['合成路线／中间体／工艺','Synthesis routes / intermediates / process','340–3,400',t('每母体 10–100 个路线或工艺对象 × 34；来自论文与专利','10–100 route or process objects per parent name × 34, from papers and patents')],['文献情报与研发事实','Literature intelligence & R&D facts','35,000–700,000',t('约 70 万记录 × 5%–20% 相关比例 × 每篇 1–5 条事实','About 700,000 records × 5%–20% relevant fraction × 1–5 facts per paper')],['商业许可数据库情报','Licensed commercial intelligence','12,000–120,000',t('每品种 200–2,000 条原始记录 × 60；与公开来源重叠，单独去重','200–2,000 raw records per product × 60; overlaps with public sources and requires deduplication')],['内部工艺／产线适配','Internal process / production fit','180–600',t('每品种 3–10 个内部适配对象 × 60；需公司内部资料','3–10 internal-fit objects per product × 60; requires internal company data')],['研发机会／战略评估','R&D opportunities / strategic assessments','60–600',t('每品种 1–10 个评估对象 × 60；由研发人员形成','1–10 assessment objects per product × 60; authored by researchers')],['决策与版本记录','Decisions & version records',t('按项目累计','Accumulates by project'),t('持续研发产生，不存在外部“全量”上限，不纳入静态资料总量','Generated during ongoing research; no external exhaustive ceiling; excluded from static source totals')]];
return `<div class="expansion-estimate"><div class="coverage-heading"><h3>${t('全品种完整采集 · 数据规模','Full-portfolio collection · data scale')}</h3><span class="review-status">${t('全库检索＋容量情景','Database counts + capacity scenarios')}</span></div><div class="coverage-metrics"><div><strong>${t('50 余种','50+')}</strong><span>${t('API · 官网 60 个产品条目纳入检索','APIs · 60 catalogue products searched')}</span></div><div><strong>${t('约 70 万','~700,000')}</strong><span>${t('公开检索记录 · 未采集全量','Public search records · not fully collected')}</span></div><div><strong>${t('百万级','Millions')}</strong><span>${t('结构化对象容量 · 高覆盖情景','Structured-object capacity · high-coverage scenario')}</span></div></div><div class="estimate-tables"><h4>${t('完整公开检索范围 · 2026-10-12','Uncapped public search scope · 2026-10-12')}</h4><p class="subtle">${t('直接查询数据库总命中数或完整公开文件，取消试点条数截断。检索命中需做相关性复核，未入库；不能据此认定全量采集完成。','Counts come from database totals or complete public files, without pilot record caps. Hits require relevance review and have not been ingested; these counts do not imply completed collection.')}</p>${table([t('数据类型','Data type'),t('检索／文件计数','Search / file count'),t('来源','Source'),t('覆盖口径','Scope')],counted.map(([zh,en,n,src,scope])=>[t(zh,en),n,src,scope]))}<h4>${t('各类数据的完整覆盖容量情景','Full-coverage capacity scenarios by data type')}</h4><p class="subtle">${t('覆盖公开、商业及内部资料，不沿用当前 11 个 API 的采集密度。以下区间是显式假设下的容量估算；上端用于高覆盖规划，未查询的类型不冒充实际总量。','Covers public, commercial and internal data without extrapolating current 11-API collection density. Ranges are capacity estimates under explicit assumptions; upper bounds support high-coverage planning and are not measured totals for unqueried types.')}</p>${table([t('数据类型','Data type'),t('预计对象／记录规模','Estimated object / record scale'),t('测算规则','Scenario rule')],scenarios.map(([zh,en,n,rule])=>[t(zh,en),n,rule]))}</div><details class="estimate-method"><summary>${t('检索范围、假设与去重口径','Search scope, assumptions & deduplication')}</summary><p>${t('官网四类 API／中间体目录共 61 个条目；剔除明确中间体 Prednisolone 21-mesyl，保留 60 个产品条目，含盐型、酯型及复方名称变体。展开 Norethindrone/Norethisterone 同义名，并补充 34 个母体／活性成分名称。未把短缩写 E2、P4 等用于广泛检索。该清单为公开目录范围，不是已确认的集团全产品主数据。','The four official API/intermediate categories contain 61 entries. Excluding the explicit intermediate Prednisolone 21-mesyl leaves 60 product entries, including salts and esters. Norethindrone/Norethisterone aliases and 34 parent / active ingredient names expand the queries. Ambiguous short aliases such as E2 and P4 are excluded. This is the public catalogue scope, not a confirmed group-wide product master.')}</p><p>${t('文献 650,044 为目录名称联合检索，677,441 为加入母体名称后的检索；同一查询内按数据库文献 ID 去重。临床为母体名称干预检索；标签为目录与母体名称字段联合检索。四类公开记录上端合计 703,214，约 70 万；企业、专利与对象提取不再次加入这个合计。文献可能包含背景提及与非目标研究，需筛选后确定可用数据。','Literature totals are 650,044 for catalogue-name searches and 677,441 after parent-name expansion, deduplicated by database ID within each query. Trials use intervention searches with parent names; labels use catalogue and parent-name fields. The four public record categories total 703,214 at the upper literature scope, about 700,000. Applicants, patents and extracted objects are not added again. Literature may contain background mentions or irrelevant studies; screening determines usable data.')}</p><p>${t('PubMed 并不穷尽所有论文、专利与地区数据库；完整覆盖仍需加入其他数据库、同义名与语言。容量情景的倍数和提取比例是规划假设，没有真实抽样验证；不同对象互相重叠，不直接相加。许可来源需有效授权，内部适配需内部资料；没有真实实验结果时保持缺失。','PubMed does not cover all papers, patents or regional databases; broader coverage requires other databases, aliases and languages. Capacity multipliers and extraction fractions are unvalidated planning assumptions. Object categories overlap and are not directly summed. Licensed sources require valid access and internal fit requires internal records; missing real assay results remain missing.')}</p><div class="estimate-links"><a class="text-button" href="https://www.xjpharma.com/en/product_235.html" target="_blank" rel="noopener">${t('仙琚产品目录','Xianju product catalogue')}</a><a class="text-button" href="data/full-scale-estimate.json" target="_blank" rel="noopener">${t('检索计数与测算记录 JSON','Query counts & scenario records JSON')}</a><a class="text-button" href="https://www.fda.gov/drugs/drug-approvals-and-databases/orange-book-data-files" target="_blank" rel="noopener">Orange Book</a></div></details></div>`;}
function dataCoverage(){const l=L.totals;return `<section class="data-coverage"><div class="coverage-heading"><h2>${t('平台数据资产','Platform data assets')}</h2><a class="text-button" href="#library">${t('浏览资料库','Browse library')}${icon('chevron')}</a></div><div class="coverage-metrics"><div><strong>${formatCount(l.records)}</strong><span>${t('来源记录','Source records')}</span></div><div><strong>${formatCount(l.documents)}</strong><span>${t('去重文档','Unique documents')}</span></div><div><strong>${formatCount(l.public_records)}</strong><span>${t('公开来源记录','Public-source records')}</span></div><div><strong>${l.apis}</strong><span>${t('试点原料药','Pilot APIs')}</span></div></div><div class="source-distribution">${L.sources.map(s=>`<button data-library-source="${s.id}"><span>${s.name}</span><b>${formatCount(s.records)}</b><span class="distribution-track"><i style="width:${s.records/l.public_records*100}%"></i></span></button>`).join('')}<button data-library-source="licensed"><span>${t('许可来源','Licensed sources')}</span><b>${formatCount(l.licensed_records)}</b><small>${t('仅汇总','Counts only')}</small></button></div><div class="coverage-footnote"><span>${t('采集快照','Collection snapshot')}: 2026-08-27 · ${t('整理','Compiled')}: 2026-10-08</span><span>${badge('REAL')} ${t('来源元数据 · 内容待复核','Source metadata · content review pending')}</span></div>${expansionEstimate()}</section>`;}
function libraryDocs(){return L.documents.filter(d=>(librarySource==='all'||d.source===librarySource)&&(libraryApi==='all'||d.associations.some(a=>a.code===libraryApi))&&(!libraryQuery||[d.title,d.external_id,...d.associations.map(a=>a.name)].join(' ').toLowerCase().includes(libraryQuery.toLowerCase()))&&(libraryMatch==='all'||d.associations.some(a=>(libraryApi==='all'||a.code===libraryApi)&&a.name_match)));}
function associationLabel(d){if(d.source==='clinical_trials'||d.source==='orange_book'||d.source==='openfda_label'){const matches=d.associations.filter(a=>libraryApi==='all'||a.code===libraryApi);return matches.some(a=>a.name_match)?t('名称匹配','Name matched'):t('检索关联','Search associated');}return d.source==='pubmed'&&d.fields.title_mentions_name?t('标题提及','Title mention'):t('检索关联','Search associated');}
function catalogRows(docs){return docs.map(d=>[`<span class="source-name">${L.sources.find(s=>s.id===d.source).name}</span><small class="record-id mono">${esc(d.external_id)}</small>`,`<button class="record-title" data-doc="${d.id}">${esc(d.title)}</button><small class="record-associations">${d.associations.map(a=>esc(a.name)).join(' · ')}</small>`,`<span class="association-status ${associationLabel(d)===t('名称匹配','Name matched')?'matched':''}">${associationLabel(d)}</span>`,esc(d.source_date||'—'),`<button class="text-button" data-doc="${d.id}" aria-label="${t('详情','Details')} ${esc(d.external_id)}">${t('详情','Details')}${icon('chevron')}</button>`]);}
function libraryResults(){if(librarySource==='licensed')return `<div class="licensed-summary"><h2>${t('许可来源','Licensed sources')}</h2><div class="licensed-counts"><b>${formatCount(L.totals.licensed_records)}</b><span>${t('来源记录','source records')}</span><b>${formatCount(L.totals.licensed_documents)}</b><span>${t('去重文档','unique documents')}</span></div><p>${t('仅显示汇总数量，记录正文、标题与申请人不公开。','Aggregate counts only. Record content, titles and assignees are not published.')}</p></div>`;const filtered=libraryDocs();const pages=Math.max(1,Math.ceil(filtered.length/20));libraryPage=Math.min(libraryPage,pages);const page=filtered.slice((libraryPage-1)*20,libraryPage*20);return `<div class="catalog-resulthead"><span>${formatCount(filtered.length)} ${t('份文档','documents')} ${badge('REAL')}</span><small>${t('名称匹配仅为来源字段匹配；检索关联的归属待复核。','Name matching reflects source fields; search-associated attribution remains unreviewed.')}</small></div>${page.length?table([t('来源 / 编号','Source / identifier'),t('记录','Record'),t('关联方式','Association'),t('来源日期','Source date'),`<span class="sr-only">${t('操作','Actions')}</span>`],catalogRows(page),'catalog-table'):empty(t('没有匹配记录','No matching records'),t('调整来源、分子或关键词。','Adjust source, molecule or keyword.'))}<div class="pagination"><span>${t('去重文档','Unique documents')} · ${libraryPage} / ${pages}</span><div><button id="library-prev" ${libraryPage===1?'disabled':''}>${t('上一页','Previous')}</button><button id="library-next" ${libraryPage===pages?'disabled':''}>${t('下一页','Next')}</button></div></div>`;}
function libraryView(){return `<div class="pageheading"><div><div class="breadcrumb">${t('平台资料库','Platform library')}</div><h1>${t('数据资源','Data resources')}</h1><p>${formatCount(L.totals.records)} ${t('条来源记录','source records')} · ${formatCount(L.totals.documents)} ${t('份去重文档','unique documents')}</p></div><button id="catalog-export">${icon('download')}${t('导出公开目录','Export public catalog')}</button></div><div class="library-sources">${[{id:'all',name:t('公开来源','Public sources'),documents:L.totals.public_documents},...L.sources,{id:'licensed',name:t('许可来源','Licensed sources'),documents:L.totals.licensed_documents}].map(s=>`<button data-source="${s.id}" class="${librarySource===s.id?'active':''}" aria-pressed="${librarySource===s.id}"><span>${s.name}</span><b>${formatCount(s.documents)}</b><small>${s.id==='licensed'?t('仅汇总','Counts only'):t('去重文档','Unique documents')}</small></button>`).join('')}</div><section class="card catalog-card"><div class="catalog-filters"><div class="search-field"><label class="sr-only" for="library-search">${t('搜索标题、编号或分子','Search title, identifier or molecule')}</label>${icon('search')}<input id="library-search" type="search" value="${esc(libraryQuery)}" placeholder="${t('搜索标题、编号或分子','Search title, identifier or molecule')}"></div><div><label class="sr-only" for="library-api">${t('原料药','API')}</label><select id="library-api"><option value="all">${t('全部原料药','All APIs')}</option>${L.compounds.map(c=>`<option value="${c.code}" ${libraryApi===c.code?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div><label class="sr-only" for="library-match">${t('关联方式','Association')}</label><select id="library-match"><option value="all" ${libraryMatch==='all'?'selected':''}>${t('全部关联','All associations')}</option><option value="name" ${libraryMatch==='name'?'selected':''}>${t('名称匹配','Name matched')}</option></select></div></div><div id="catalog-results">${libraryResults()}</div></section><div class="library-provenance"><span>${t('采集','Collected')}: 2026-08-27 · ${t('快照整理','Compiled')}: 2026-10-08</span><span>${formatCount(L.totals.public_records)} ${t('条公开关联 /','public associations /')} ${formatCount(L.totals.public_documents)} ${t('份公开文档','public documents')}</span></div><dialog id="record-dialog" aria-labelledby="record-dialog-title"><div id="record-dialog-content"></div></dialog>`;}
function displaySourceField(k,v){const raw=Array.isArray(v)?v.join(' · '):String(v);if(lang==='en')return raw;const phases={NA:'不适用',EARLY_PHASE1:'早期 I 期',PHASE1:'I 期',PHASE2:'II 期',PHASE3:'III 期',PHASE4:'IV 期'};const statuses={COMPLETED:'已完成',TERMINATED:'已终止',RECRUITING:'招募中',ACTIVE_NOT_RECRUITING:'进行中，不再招募',NOT_YET_RECRUITING:'尚未招募',SUSPENDED:'已暂停',WITHDRAWN:'已撤回',UNKNOWN:'状态未知',ENROLLING_BY_INVITATION:'邀请入组'};return (k==='phase'?phases[raw]:k==='status'?statuses[raw]:null)||raw;}
function recordDetails(doc){const fieldLabels={registry_id:t('登记编号','Registry ID'),start_date:t('开始日期','Start date'),completion_date:t('完成日期','Completion date'),application_number:t('申请编号','Application number'),effective_time:t('标签日期','Label date'),title_mentions_name:t('标题名称提及','Name mentioned in title'),mesh_terms:t('主题词','MeSH terms'),phase:t('阶段','Phase'),status:t('状态','Status'),sponsor:t('申办方','Sponsor'),conditions:t('研究条件','Conditions'),interventions:t('干预','Interventions'),has_results:t('结果登记','Results'),updated:t('更新日期','Updated'),journal:t('期刊','Journal'),published:t('发表日期','Published'),brand_name:t('商品名','Brand name'),generic_name:t('通用名','Generic name'),applicant:t('申请人','Applicant'),dosage_form:t('剂型','Dosage form'),strength:t('规格','Strength'),route:t('途径','Route'),ingredient:t('成分','Ingredient'),approval_date:t('批准日期','Approval date')};return `<div class="dialog-head"><div><span class="small-label">${L.sources.find(s=>s.id===doc.source).name} · ${esc(doc.external_id)}</span><h2 id="record-dialog-title">${esc(doc.title)}</h2></div><button id="record-dialog-close" aria-label="${t('关闭记录','Close record')}">×</button></div><div class="record-meta">${badge('REAL')}<span class="review-status">${t('内容待复核','Content review pending')}</span>${doc.date_anomaly?`<span class="review-status">${t('日期待核对','Date needs review')}</span>`:''}</div>${table([t('关联分子','Associated molecule'),t('方式','Association')],doc.associations.map(a=>[esc(a.name),a.name_match?t('名称匹配','Name matched'):t('检索关联','Search associated')]))}<dl class="record-fields">${Object.entries(doc.fields).filter(([k,v])=>v!==null&&v!==''&&!(Array.isArray(v)&&!v.length)).map(([k,v])=>`<dt>${fieldLabels[k]||esc(k)}</dt><dd>${esc(displaySourceField(k,v))}</dd>`).join('')}</dl><div class="record-provenance"><span>${t('采集日期','Retrieved')}: ${esc(doc.retrieved_at.slice(0,10))}</span><details><summary>SHA-256</summary><p class="mono">${esc(doc.sha256)}</p></details></div>${doc.url?`<a class="button primary" href="${esc(doc.url)}" target="_blank" rel="noopener">${t('打开原始来源','Open original source')}${icon('arrow')}</a>`:`<span class="subtle">${t('未提供来源链接','Source URL unavailable')}</span>`}`;}
function bindCatalogResults(){const prev=document.querySelector('#library-prev'),next=document.querySelector('#library-next');if(prev)prev.onclick=()=>{libraryPage--;updateCatalog();};if(next)next.onclick=()=>{libraryPage++;updateCatalog();};document.querySelectorAll('[data-doc]').forEach(b=>b.onclick=()=>{const doc=L.documents.find(d=>d.id===Number(b.dataset.doc));const dialog=document.querySelector('#record-dialog');document.querySelector('#record-dialog-content').innerHTML=recordDetails(doc);document.querySelector('#record-dialog-close').onclick=()=>dialog.close();dialog.showModal();});}
function updateCatalog(){document.querySelector('#catalog-results').innerHTML=libraryResults();bindCatalogResults();}
function bindLibrary(){if(librarySource==='licensed')document.querySelectorAll('.catalog-filters input,.catalog-filters select').forEach(e=>e.disabled=true);document.querySelectorAll('[data-library-source]').forEach(b=>b.onclick=()=>{librarySource=b.dataset.librarySource;libraryPage=1;libraryApi='all';libraryQuery='';libraryMatch='all';navigate('library');});document.querySelectorAll('[data-library-api]').forEach(b=>b.onclick=()=>{libraryApi=b.dataset.libraryApi;librarySource='all';libraryPage=1;libraryQuery='';libraryMatch='all';navigate('library');});document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{librarySource=b.dataset.source;libraryPage=1;if(librarySource==='licensed'){libraryApi='all';libraryQuery='';libraryMatch='all';}render();});const search=document.querySelector('#library-search');if(search)search.oninput=()=>{libraryQuery=search.value;libraryPage=1;updateCatalog();};const api=document.querySelector('#library-api');if(api)api.onchange=()=>{libraryApi=api.value;libraryPage=1;updateCatalog();};const match=document.querySelector('#library-match');if(match)match.onchange=()=>{libraryMatch=match.value;libraryPage=1;updateCatalog();};const exportButton=document.querySelector('#catalog-export');if(exportButton)exportButton.onclick=()=>{const data={data_class:'REAL',source:'archived public-source metadata',snapshot_sha256:L.snapshot_sha256,collected_at:L.collected_at,documents:librarySource==='licensed'?[]:libraryDocs(),licensed:librarySource==='licensed'?L.licensed:undefined};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='SteroidAtlas-public-catalog.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};bindCatalogResults();}

function render(){const view=currentView();document.documentElement.lang=lang==='zh'?'zh-CN':'en';const routes=[['home','grid',t('项目概览','Overview')],['library','layers',t('数据资源','Data resources')],['workbench','molecule',t('分子工作台','Workbench')],['report','report',t('研究报告','Reports')],['evidence','source',t('来源与记录','Sources & records')],['platform','layers','API 360']];document.querySelector('#app').innerHTML=`<div class="app-shell"><aside class="app-sidebar"><a class="brand" href="#home"><img src="assets/atlas.svg" alt="">SteroidAtlas</a><div class="workspace-label">${t('研发工作空间','Research workspace')}</div><nav class="main-nav" aria-label="${t('主导航','Main navigation')}">${routes.map(([id,i,title])=>`<a href="#${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(i)}${title}</a>`).join('')}</nav><div class="project-nav"><span class="small-label">${t('项目','Projects')}</span>${Object.entries(cases).map(([id,c])=>`<button data-case="${id}" class="${caseId===id?'active':''}" aria-pressed="${caseId===id}"><span class="project-dot"></span><span>${c.title[lang==='zh'?0:1]}</span><small>${c.project}</small></button>`).join('')}</div><div class="sidebar-bottom"><div class="avatar">S</div><div><b>Sylvia</b><small>${t('研发','Research & development')}</small></div></div></aside><div class="main-shell"><header class="app-header"><div><span>${view==='library'||view==='platform'?t('研发工作空间','Research workspace'):projectTitle()}</span>${icon('chevron')}<span>${routes.find(r=>r[0]===view)[2]}</span></div><div class="header-tools"><span class="sample-label">${t('样例项目','Sample project')}</span><button id="lang" aria-label="${lang==='zh'?'EN — switch to English':'中文 — 切换到中文'}">${lang==='zh'?'EN':'中文'}</button></div></header><main id="main-content">${view==='home'?dashboard():view==='library'?libraryView():view==='workbench'?workbench():view==='report'?reportView():view==='evidence'?sourcesView():platformView()}</main><footer><span>SteroidAtlas</span>${legend()}<a href="#evidence">${t('来源与方法','Sources & methods')}</a></footer></div></div>`;bind();}
function navigate(view){if(currentView()===view){render();}else location.hash=view;}
function openMolecule(code){const mol=D.molecules.find(m=>m.demo_code===code);if(!mol)return;if(code.startsWith('DEMO')){caseId='A';activeCode=code;}else if(code==='API-007')caseId='B';else if(code==='API-005')caseId='C';else return;step=2;navigate('workbench');}
function reportPayload(){return {version:versions[caseId],case:caseId,title:cases[caseId].title,notice:'Public structures / computed descriptors; SIMULATED assays; VIRTUAL_UNTESTED hypotheses; professional review pending.',original_input_sha256:caseId==='C'?null:D.analysis[caseId].sha256,molecules:selected(),experiments:experiments(),analysis:{data_class:caseId==='C'||versions[caseId]===2?'SIMULATED':'VIRTUAL',source:caseId==='C'||versions[caseId]===2?'illustrative canned scenario':'saved Codex analysis / editorial summary',summary:analysisText()},hypotheses:M.modifications,archived_candidates:caseId==='A'?D.candidates:[],next_experiment:{data_class:'SIMULATED',source:'illustrative experiment plan',plan:loopPlan()},loop_result:versions[caseId]===2?M.loops[caseId]:null};}
function download(format){const data=reportPayload();let body=format==='json'?JSON.stringify(data,null,2):`<!doctype html><html lang="${lang}"><meta charset="utf-8"><title>SteroidAtlas research report</title><style>body{font:16px/1.7 system-ui;max-width:950px;margin:40px auto;padding:20px}pre{white-space:pre-wrap;overflow-wrap:anywhere}h1{color:#344c62}</style><h1>${esc(projectTitle())} · v${versions[caseId]}</h1><p>${esc(data.notice)}</p><h2>${t('研究判断','Assessment')}</h2><p>${esc(data.analysis.summary)}</p><h2>${t('实验计划','Experiment plan')}</h2><p>${esc(data.next_experiment.plan)}</p><h2>${t('来源与记录','Sources & records')}</h2><pre>${esc(JSON.stringify(data,null,2))}</pre></html>`;const u=URL.createObjectURL(new Blob([body],{type:format==='html'?'text/html;charset=utf-8':'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=`SteroidAtlas-${cases[caseId].project}-v${versions[caseId]}.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function bind(){bindLibrary();document.querySelector('#lang').onclick=()=>{lang=lang==='zh'?'en':'zh';render();};document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{caseId=b.dataset.case;step=1;experimentFilter='all';render();});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.querySelectorAll('[data-mol]').forEach(b=>b.onclick=()=>openMolecule(b.dataset.mol));document.querySelectorAll('[data-step-jump]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.stepJump);navigate('workbench');});document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);render();});const select=document.querySelector('#molecule');if(select)select.onchange=()=>{activeCode=select.value;render();};const prev=document.querySelector('#prev');if(prev)prev.onclick=()=>{if(step>1){step--;render();}};const next=document.querySelector('#next');if(next)next.onclick=()=>{if(step<11){step++;render();}else document.querySelector('#loop').scrollIntoView({behavior:'auto'});};document.querySelectorAll('[data-search]').forEach(b=>b.onclick=()=>{searchMode=b.dataset.search;render();});document.querySelectorAll('[data-assay]').forEach(b=>b.onclick=()=>{experimentFilter=b.dataset.assay;render();});const range=document.querySelector('#threshold');if(range)range.oninput=()=>{threshold=Number(range.value);document.querySelector('#thresholdvalue').textContent=threshold;document.querySelector('#searchresults').innerHTML=searchResults();document.querySelectorAll('#searchresults [data-mol]').forEach(b=>b.onclick=()=>openMolecule(b.dataset.mol));};const norm=document.querySelector('#normalize');if(norm)norm.onclick=()=>{const input=document.querySelector('#smiles').value.trim();const m=D.molecules.find(m=>m.smiles===input||m.canonical_smiles===input);const out=document.querySelector('#canonical');if(m){out.classList.remove('hidden');out.innerHTML=`<dl><dt>Canonical SMILES</dt><dd class="mono">${esc(m.canonical_smiles)}</dd><dt>InChIKey</dt><dd class="mono">${esc(m.inchikey)}</dd></dl>${badge('REAL')}`;document.querySelector('#inputstatus').textContent=t('已读取预计算结构记录。','Precomputed structure record loaded.');}else{out.classList.add('hidden');document.querySelector('#inputstatus').textContent=t('没有匹配的预计算记录。','No matching precomputed record.');}};const record=document.querySelector('#record');if(record)record.onclick=()=>{versions[caseId]=2;step=7;experimentFilter='all';render();};const reset=document.querySelector('#reset');if(reset)reset.onclick=()=>{versions[caseId]=1;render();};document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>download(b.dataset.download));}
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'auto'});});render();
